const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Lut Desert location (central coordinates)
  const lutDesert = ee.Geometry.Point([59.0, 30.5]).buffer(50000); // 50km radius

  // 2. Load MODIS LST data for 2018
  let collection = ee.ImageCollection('MODIS/006/MOD11A1')
    .filterDate('2018-01-01', '2018-12-31')
    .filterBounds(lutDesert);

  const collectionSize = collection.size().getInfo();
  console.log('Collection size (MOD11A1):', collectionSize);

  if (collectionSize === 0) {
    // Try Terra+Aqua combined product
    collection = ee.ImageCollection('MODIS/006/MYD11A1')
      .filterDate('2018-01-01', '2018-12-31')
      .filterBounds(lutDesert);

    const fallbackSize = collection.size().getInfo();
    console.log('Fallback collection size (MYD11A1):', fallbackSize);

    if (fallbackSize === 0) {
      console.log('No MODIS LST images found for Lut Desert in 2018.');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Process LST data: Convert from Kelvin to Celsius and apply QA mask
  const processLST = (image) => {
    const lst = image.select('LST_Day_1km').multiply(0.02).subtract(273.15); // Scale and convert K to C
    const qa = image.select('QC_Day');
    const mask = qa.bitwiseAnd(3).lte(1); // Keep only good quality (mandatory QA bits 0-1)
    return lst.updateMask(mask);
  };

  const lstCollection = collection.map(processLST);

  // 4. Calculate maximum temperature across all images
  const maxLST = lstCollection.max();

  // 5. Get statistics
  const stats = maxLST.reduceRegion({
    reducer: ee.Reducer.max().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: lutDesert,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo();

  const maxTemp = stats.LST_Day_1km_max;
  const pixelCount = stats.LST_Day_1km_count;

  console.log('Valid pixels:', pixelCount);
  console.log('Maximum LST (C):', maxTemp ? maxTemp.toFixed(2) : 'null');

  // 6. Validation and final answer
  if (pixelCount === 0 || pixelCount === null) {
    console.log('No valid pixels after QA masking.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (maxTemp === null || maxTemp === undefined || isNaN(maxTemp)) {
    console.log('Temperature calculation returned invalid result.');
    console.log('<answer>C3</answer>');
    return;
  }

  if (maxTemp > 100 || maxTemp < -100) {
    console.log('Temperature value outside realistic range.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Final determination
  if (maxTemp > 75) {
    console.log('Lut Desert exceeded 75C in 2018.');
    console.log('<answer>A</answer>');
  } else {
    console.log('Lut Desert did not exceed 75C in 2018.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
